namespace ghidra.framework.main.projectdata.actions;




using docking;
using docking.action;
using docking.action;
using docking.widgets.tree;
using generic.theme;
using ghidra.framework.main.datatree;
using ghidra.framework.model;
using ghidra.util;

public class ProjectDataCutAction : ProjectDataCopyCutBaseAction {
	private static readonly Icon ICON = new GIcon("icon.projectdata.cut");

	public ProjectDataCutAction(string owner, string group) : base("Cut", owner)
    {
		setPopupMenuData(new MenuData(new string[] { "Cut" }, ICON, group));
		setKeyBindingData(new KeyBindingData('X', DockingUtils.CONTROL_KEY_MODIFIER_MASK));
		setHelpLocation(new HelpLocation("FrontEndPlugin", "Cut"));
	}

	/* @Override */
	protected void actionPerformed(FrontEndProjectTreeContext context) {
		TreePath[] paths = adjustSelectionPaths(context.getSelectionPaths());

		DataTreeClipboardUtils.setClipboardContents(context.getTree(), paths);

		markNodesCut(paths);
	}

	/* @Override */
	protected bool isEnabledForContext(FrontEndProjectTreeContext context) {
		if (!context.isInActiveProject() || !context.hasOneOrMoreFilesAndFolders()) {
			return false;
		}
		return !context.containsRootFolder() && canMarkNodesCut(context.getSelectionPaths());
	}

	private bool canMarkNodesCut(TreePath[] paths) {
		foreach (TreePath treePath in paths) {
			GTreeNode node = (GTreeNode) treePath.getLastPathComponent();
			DomainFolder folder;
			if (node is DomainFileNode fileNode) {
				folder = fileNode.getDomainFile().getParent();
			}
			else if (node is DomainFolderNode folderNode) {
				folder = folderNode.getDomainFolder();
			}
			else {
				return false;
			}
			if (!folder.isInWritableProject()) {
				// linked content may reside within a read-only project view
				return false;
			}
		}
		return true;
	}

	private void markNodesCut(TreePath[] paths) {
		foreach (TreePath treePath in paths) {
			GTreeNode node = (GTreeNode) treePath.getLastPathComponent();
			if (node is Cuttable) {
				((Cuttable) node).setIsCut(true);
			}
		}
	}

}
